package finance.governance;

import finance.account.*;
import finance.company.*;
import finance.data.EconomySavedData;
import finance.stock.*;
import finance.util.ProportionalAllocator;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.util.*;

public final class CorporateActionManager {
 public static final int MAX_ACTIONS=1024,MAX_ACCEPTANCES=4096;private static final Map<UUID,BuybackPlan>BUYBACKS=new LinkedHashMap<>();private static final Map<UUID,TenderOffer>TENDERS=new LinkedHashMap<>();private static final List<CorporateAnnouncement>ANNOUNCEMENTS=new ArrayList<>();private static final Map<UUID,UUID>CONTROLLERS=new LinkedHashMap<>();private static final Set<String>KEYS=new HashSet<>();private CorporateActionManager(){}
 public static synchronized Result startBuyback(UUID requester,UUID companyId,long price,long maxShares,int duration,long day,String key){Company c=CompanyManager.getCompany(companyId);Stock s=StockMarketManager.getStockByCompanyId(companyId);String k="buyback:"+key;CompanyProposal authorization=approvedProposal(key,CompanyProposalType.SHARE_BUYBACK,companyId);if(requester==null||c==null||s==null||!GovernanceAuthorizationService.mayManage(requester,companyId)||authorization==null||authorization.getValue1()!=price||authorization.getValue2()!=maxShares||authorization.getValue3()!=duration||price<=0||maxShares<=0||duration<1||duration>90||KEYS.contains(k))return Result.fail("Approved shareholder proposal required for buyback");if(!ensureCapacity(BUYBACKS))return Result.fail("Corporate action history is full");if(BUYBACKS.values().stream().anyMatch(x->x.companyId().equals(companyId)&&x.status()==CapitalActionStatus.OPEN))return Result.fail("Company already has an open buyback");long budget=multiply(price,maxShares);long minimum=Math.max(1,c.estimateDailyOperatingCost());if(budget<=0||c.getCash()-minimum<budget)return Result.fail("Company cash after minimum operating reserve is insufficient");UUID id=UUID.randomUUID(),escrow=escrow(id);ensureZeroEscrow(escrow);if(!c.withdraw(budget)||!AccountManager.deposit(escrow,budget)){if(c.canDeposit(budget))c.deposit(budget);return Result.fail("Buyback escrow failed");}BUYBACKS.put(id,new BuybackPlan(id,companyId,escrow,s.getSymbol(),price,maxShares,day,day+duration,budget,CapitalActionStatus.OPEN));KEYS.add(k);announce(companyId,CorporateAnnouncement.Type.BUYBACK,day,id,"buyback.open","price="+price+",shares="+maxShares);record(companyId,escrow,budget,TransactionType.COMPANY_BUYBACK,requester,s.getSymbol(),maxShares);EconomySavedData.markDirty();return Result.ok(id,"Buyback opened");}
 public static synchronized Result acceptBuyback(UUID holder,UUID planId,long shares,long day,String key){BuybackPlan p=BUYBACKS.get(planId);String k="buyback-accept:"+key;if(holder==null||p==null||p.status()!=CapitalActionStatus.OPEN||day>p.endDay()||shares<=0||key==null||key.isBlank()||KEYS.contains(k)||p.accepted().size()>=MAX_ACCEPTANCES)return Result.fail("Invalid buyback acceptance");if(lockedSharesFor(holder,p.symbol())>0)return Result.fail("Shares are already locked by another corporate action");long cost=StockPortfolioManager.getHolding(holder,p.symbol()).getAverageCost();if(!StockPortfolioManager.removeHolding(holder,p.symbol(),shares)||!p.accept(holder,shares,cost)){StockPortfolioManager.addHolding(holder,p.symbol(),shares,cost);return Result.fail("Insufficient shares");}KEYS.add(k);EconomySavedData.markDirty();return Result.ok(planId,"Shares locked for buyback");}
 public static synchronized Result startTender(UUID buyer,UUID companyId,long price,long target,long minimum,int duration,long day,String key){Company c=CompanyManager.getCompany(companyId);Stock s=StockMarketManager.getStockByCompanyId(companyId);String k="tender:"+key;if(buyer==null||c==null||s==null||price<=0||target<=0||minimum<=0||minimum>target||duration<1||duration>90||key==null||key.isBlank()||KEYS.contains(k))return Result.fail("Invalid tender offer");if(!ensureCapacity(TENDERS))return Result.fail("Corporate action history is full");long funds=multiply(price,target);UUID id=UUID.randomUUID(),escrow=escrow(id);ensureZeroEscrow(escrow);if(funds<=0||!AccountManager.moveFunds(buyer,escrow,funds))return Result.fail("Tender funds are insufficient");TENDERS.put(id,new TenderOffer(id,buyer,companyId,escrow,s.getSymbol(),price,target,minimum,day,day+duration,funds,CapitalActionStatus.OPEN));KEYS.add(k);announce(companyId,CorporateAnnouncement.Type.TENDER,day,id,"tender.open","price="+price+",target="+target);EconomySavedData.markDirty();return Result.ok(id,"Tender offer opened");}
 public static synchronized Result acceptTender(UUID holder,UUID offerId,long shares,long day,String key){TenderOffer o=TENDERS.get(offerId);String k="tender-accept:"+key;if(holder==null||o==null||o.status()!=CapitalActionStatus.OPEN||holder.equals(o.buyerId())||day>o.endDay()||shares<=0||key==null||key.isBlank()||KEYS.contains(k)||o.accepted().size()>=MAX_ACCEPTANCES)return Result.fail("Invalid tender acceptance");if(lockedSharesFor(holder,o.symbol())>0)return Result.fail("Shares are already locked by another corporate action");long cost=StockPortfolioManager.getHolding(holder,o.symbol()).getAverageCost();if(!StockPortfolioManager.removeHolding(holder,o.symbol(),shares)||!o.accept(holder,shares,cost)){StockPortfolioManager.addHolding(holder,o.symbol(),shares,cost);return Result.fail("Insufficient shares");}KEYS.add(k);EconomySavedData.markDirty();return Result.ok(offerId,"Shares locked for tender");}
 public static synchronized Result cancelBuyback(UUID requester,UUID planId,long day,String key){BuybackPlan p=BUYBACKS.get(planId);Company c=p==null?null:CompanyManager.getCompany(p.companyId());String k="buyback-cancel:"+key;if(p==null||c==null||p.status()!=CapitalActionStatus.OPEN||!GovernanceAuthorizationService.mayManage(requester,p.companyId())||key==null||key.isBlank()||KEYS.contains(k))return Result.fail("Invalid buyback cancellation");long cash=AccountManager.getBalance(p.escrowId());if((cash>0&&!c.canDeposit(cash))||!canRelease(p.accepted(),p.symbol()))return Result.fail("Cancellation settlement cannot be credited");returnUnallocated(p.accepted(),Map.of(),p.symbol());if(cash>0){AccountManager.withdraw(p.escrowId(),cash);c.deposit(cash);}p.status(CapitalActionStatus.CANCELLED);KEYS.add(k);announce(p.companyId(),CorporateAnnouncement.Type.BUYBACK,day,p.id(),"buyback.cancelled","refund="+cash);EconomySavedData.markDirty();return Result.ok(planId,"Buyback cancelled");}
 public static synchronized Result cancelTender(UUID requester,UUID offerId,long day,String key){TenderOffer o=TENDERS.get(offerId);String k="tender-cancel:"+key;if(o==null||o.status()!=CapitalActionStatus.OPEN||!o.buyerId().equals(requester)||key==null||key.isBlank()||KEYS.contains(k))return Result.fail("Invalid tender cancellation");long cash=AccountManager.getBalance(o.escrowId());if((cash>0&&!AccountManager.canDeposit(o.buyerId(),cash))||!canRelease(o.accepted(),o.symbol()))return Result.fail("Cancellation settlement cannot be credited");returnUnallocated(o.accepted(),Map.of(),o.symbol());if(cash>0)AccountManager.moveFunds(o.escrowId(),o.buyerId(),cash);o.status(CapitalActionStatus.CANCELLED);KEYS.add(k);announce(o.targetCompanyId(),CorporateAnnouncement.Type.TENDER,day,o.id(),"tender.cancelled","refund="+cash);EconomySavedData.markDirty();return Result.ok(offerId,"Tender cancelled");}
 public static synchronized Result retireTreasury(UUID requester,UUID companyId,long shares,long day,String key){Stock s=StockMarketManager.getStockByCompanyId(companyId);String k="treasury-retire:"+key;CompanyProposal authorization=approvedProposal(key,CompanyProposalType.TREASURY_RETIREMENT,companyId);if(s==null||shares<=0||!GovernanceAuthorizationService.mayManage(requester,companyId)||authorization==null||authorization.getValue1()!=shares||KEYS.contains(k)||!s.retireTreasuryShares(shares))return Result.fail("Approved shareholder proposal required for treasury retirement");KEYS.add(k);announce(companyId,CorporateAnnouncement.Type.BUYBACK,day,authorization.getProposalId(),"treasury.retired","shares="+shares);record(companyId,companyId,0,TransactionType.COMPANY_BUYBACK,requester,s.getSymbol(),shares);EconomySavedData.markDirty();return Result.ok(companyId,"Treasury shares retired");}
 public static synchronized boolean cancelForBankruptcy(UUID companyId,long day){Company company=CompanyManager.getCompany(companyId);if(company==null)return false;List<BuybackPlan>buybacks=BUYBACKS.values().stream().filter(p->p.companyId().equals(companyId)&&p.status()==CapitalActionStatus.OPEN).toList();List<TenderOffer>tenders=TENDERS.values().stream().filter(o->o.targetCompanyId().equals(companyId)&&o.status()==CapitalActionStatus.OPEN).toList();long companyRefund=0;for(BuybackPlan p:buybacks){long cash=AccountManager.getBalance(p.escrowId());if(companyRefund>Long.MAX_VALUE-cash||!canRelease(p.accepted(),p.symbol()))return false;companyRefund+=cash;}if(companyRefund>0&&!company.canDeposit(companyRefund))return false;for(TenderOffer o:tenders){long cash=AccountManager.getBalance(o.escrowId());if((cash>0&&!AccountManager.canDeposit(o.buyerId(),cash))||!canRelease(o.accepted(),o.symbol()))return false;}for(BuybackPlan p:buybacks){failBuyback(p,company);p.status(CapitalActionStatus.CANCELLED);announce(companyId,CorporateAnnouncement.Type.BUYBACK,day,p.id(),"buyback.bankruptcy_cancelled","");}for(TenderOffer o:tenders){failTender(o,day,"target company bankruptcy");o.status(CapitalActionStatus.CANCELLED);}return true;}
 public static synchronized void processDay(long day){for(BuybackPlan p:new ArrayList<>(BUYBACKS.values()))if(p.status()==CapitalActionStatus.OPEN&&day>=p.endDay())settleBuyback(p,day);for(TenderOffer o:new ArrayList<>(TENDERS.values()))if(o.status()==CapitalActionStatus.OPEN&&day>=o.endDay())settleTender(o,day);for(Company c:CompanyManager.getCompanies())if(c.isPublic())updateControl(c.getCompanyId(),day,c.getCompanyId());}
 private static void settleBuyback(BuybackPlan p,long day){Stock s=StockMarketManager.getStock(p.symbol());Company c=CompanyManager.getCompany(p.companyId());long total=sum(p.accepted());long acquired=Math.min(total,p.maxShares());Map<UUID,Long>allocation=allocate(acquired,p.accepted());long spent=multiply(p.price(),acquired);long refund=spent<0?0:p.budget()-spent;if(s==null||c==null||spent<0||acquired>s.getVotingShares()||!precheckSellers(allocation,p.price())||!canReleaseUnallocated(p.accepted(),allocation,p.symbol())||(refund>0&&!c.canDeposit(refund))){failBuyback(p,c);return;}for(var e:allocation.entrySet()){long payment=multiply(p.price(),e.getValue());if(!AccountManager.moveFunds(p.escrowId(),e.getKey(),payment))throw new IllegalStateException("validated seller payment failed");record(p.companyId(),e.getKey(),payment,TransactionType.COMPANY_BUYBACK,e.getKey(),p.symbol(),e.getValue());}returnUnallocated(p.accepted(),allocation,p.symbol());if(refund>0){if(!AccountManager.withdraw(p.escrowId(),refund)||!c.deposit(refund))throw new IllegalStateException("validated buyback refund failed");}if(acquired>0&&!s.addTreasuryShares(acquired))throw new IllegalStateException("validated treasury settlement failed");p.status(CapitalActionStatus.COMPLETED);announce(p.companyId(),CorporateAnnouncement.Type.BUYBACK,day,p.id(),"buyback.completed","shares="+acquired+",spent="+spent);EconomySavedData.markDirty();}
 private static void settleTender(TenderOffer o,long day){long accepted=sum(o.accepted());if(accepted<o.minShares()){failTender(o,day,"minimum not reached");return;}long acquired=Math.min(accepted,o.targetShares());Map<UUID,Long>allocation=allocate(acquired,o.accepted());long spent=multiply(o.price(),acquired),refund=spent<0?0:o.maxFunds()-spent;if(spent<0||!StockPortfolioManager.canAddHolding(o.buyerId(),o.symbol(),acquired)||!precheckSellers(allocation,o.price())||!canReleaseUnallocated(o.accepted(),allocation,o.symbol())||(refund>0&&!AccountManager.canDeposit(o.buyerId(),refund))){failTender(o,day,"settlement precheck failed");return;}for(var e:allocation.entrySet()){long payment=multiply(o.price(),e.getValue());if(!AccountManager.moveFunds(o.escrowId(),e.getKey(),payment))throw new IllegalStateException("validated tender payment failed");}if(!StockPortfolioManager.addHolding(o.buyerId(),o.symbol(),acquired,o.price()))throw new IllegalStateException("validated tender credit failed");returnUnallocated(o.accepted(),allocation,o.symbol());if(refund>0&&!AccountManager.moveFunds(o.escrowId(),o.buyerId(),refund))throw new IllegalStateException("validated tender refund failed");o.status(CapitalActionStatus.COMPLETED);updateControl(o.targetCompanyId(),day,o.id());announce(o.targetCompanyId(),CorporateAnnouncement.Type.TENDER,day,o.id(),"tender.completed","shares="+acquired+",spent="+spent);record(o.buyerId(),o.targetCompanyId(),spent,TransactionType.COMPANY_TENDER,o.buyerId(),o.symbol(),acquired);EconomySavedData.markDirty();}
 private static void updateControl(UUID companyId,long day,UUID business){var snapshot=ShareholderRegistryService.snapshot(companyId,day);var top=snapshot.largest();UUID old=CONTROLLERS.get(companyId),next=top!=null&&top.votingPercent()>50&&!top.id().equals(ShareholderRegistryService.SYSTEM_LIQUIDITY_HOLDER)?top.id():null;if(!Objects.equals(old,next)){if(next==null)CONTROLLERS.remove(companyId);else CONTROLLERS.put(companyId,next);announce(companyId,CorporateAnnouncement.Type.CONTROL_CHANGE,day,business,"control.changed","from="+old+",to="+next);}}
 private static boolean failBuyback(BuybackPlan p,Company c){long cash=AccountManager.getBalance(p.escrowId());if(c==null||!canRelease(p.accepted(),p.symbol())||(cash>0&&!c.canDeposit(cash)))return false;returnUnallocated(p.accepted(),Map.of(),p.symbol());if(cash>0&&(!AccountManager.withdraw(p.escrowId(),cash)||!c.deposit(cash)))throw new IllegalStateException("validated buyback failure refund failed");p.status(CapitalActionStatus.FAILED);EconomySavedData.markDirty();return true;}private static boolean failTender(TenderOffer o,long day,String reason){long cash=AccountManager.getBalance(o.escrowId());if(!canRelease(o.accepted(),o.symbol())||(cash>0&&!AccountManager.canDeposit(o.buyerId(),cash)))return false;returnUnallocated(o.accepted(),Map.of(),o.symbol());if(cash>0&&!AccountManager.moveFunds(o.escrowId(),o.buyerId(),cash))throw new IllegalStateException("validated tender failure refund failed");o.status(CapitalActionStatus.FAILED);announce(o.targetCompanyId(),CorporateAnnouncement.Type.TENDER,day,o.id(),"tender.failed",reason);EconomySavedData.markDirty();return true;}
 private static boolean precheckSellers(Map<UUID,Long>a,long price){for(var e:a.entrySet()){long cash=multiply(price,e.getValue());if(cash<=0||!AccountManager.canDeposit(e.getKey(),cash))return false;}return true;}private static void returnUnallocated(Map<UUID,Long>accepted,Map<UUID,Long>allocated,String symbol){Map<UUID,Long>costs=costsFor(symbol,accepted);for(var e:accepted.entrySet()){long q=e.getValue()-allocated.getOrDefault(e.getKey(),0L);if(q>0&&!StockPortfolioManager.addHolding(e.getKey(),symbol,q,costs.getOrDefault(e.getKey(),0L)))throw new IllegalStateException("locked share release failed");}}
 private static Map<UUID,Long> costsFor(String symbol,Map<UUID,Long>accepted){for(BuybackPlan p:BUYBACKS.values())if(p.symbol().equals(symbol)&&p.accepted()==accepted)return p.acceptedCosts();for(TenderOffer o:TENDERS.values())if(o.symbol().equals(symbol)&&o.accepted()==accepted)return o.acceptedCosts();return Map.of();}
 private static boolean canRelease(Map<UUID,Long> accepted,String symbol){for(var e:accepted.entrySet())if(e.getValue()>0&&!StockPortfolioManager.canAddHolding(e.getKey(),symbol,e.getValue()))return false;return true;}
 private static boolean canReleaseUnallocated(Map<UUID,Long>accepted,Map<UUID,Long>allocated,String symbol){for(var e:accepted.entrySet()){long quantity=e.getValue()-allocated.getOrDefault(e.getKey(),0L);if(quantity>0&&!StockPortfolioManager.canAddHolding(e.getKey(),symbol,quantity))return false;}return true;}
 private static Map<UUID,Long> allocate(long amount,Map<UUID,Long>weights){Map<UUID,Long>out=new LinkedHashMap<>();for(var a:ProportionalAllocator.allocate(amount,weights))if(a.amount()>0)out.put(a.id(),a.amount());return out;}private static long lockedSharesFor(UUID h,String symbol){long n=0;for(var p:BUYBACKS.values())if(p.status()==CapitalActionStatus.OPEN&&p.symbol().equals(symbol))n=add(n,p.accepted().getOrDefault(h,0L));for(var o:TENDERS.values())if(o.status()==CapitalActionStatus.OPEN&&o.symbol().equals(symbol))n=add(n,o.accepted().getOrDefault(h,0L));return n;}public static synchronized Map<UUID,Long>lockedShares(String symbol){Map<UUID,Long>m=new LinkedHashMap<>();for(var p:BUYBACKS.values())if(p.status()==CapitalActionStatus.OPEN&&p.symbol().equals(symbol))p.accepted().forEach((k,v)->m.merge(k,v,CorporateActionManager::add));for(var o:TENDERS.values())if(o.status()==CapitalActionStatus.OPEN&&o.symbol().equals(symbol))o.accepted().forEach((k,v)->m.merge(k,v,CorporateActionManager::add));return m;}
 public static Map<UUID,BuybackPlan>buybacks(){return Collections.unmodifiableMap(BUYBACKS);}public static Map<UUID,TenderOffer>tenders(){return Collections.unmodifiableMap(TENDERS);}public static List<CorporateAnnouncement>announcements(){return List.copyOf(ANNOUNCEMENTS);}public static Map<UUID,UUID>controllers(){return Collections.unmodifiableMap(CONTROLLERS);}public static Set<String>keys(){return Collections.unmodifiableSet(KEYS);}public static boolean putBuybackDirect(BuybackPlan p){if(p==null)return false;BUYBACKS.put(p.id(),p);return true;}public static boolean putTenderDirect(TenderOffer o){if(o==null)return false;TENDERS.put(o.id(),o);return true;}public static void putAnnouncementDirect(CorporateAnnouncement a){if(a!=null){ANNOUNCEMENTS.add(a);while(ANNOUNCEMENTS.size()>2048)ANNOUNCEMENTS.remove(0);}}public static void putControllerDirect(UUID c,UUID h){if(c!=null&&h!=null)CONTROLLERS.put(c,h);}public static void putKeyDirect(String k){if(k!=null&&!k.isBlank())KEYS.add(k);}public static void clearDirect(){BUYBACKS.clear();TENDERS.clear();ANNOUNCEMENTS.clear();CONTROLLERS.clear();KEYS.clear();}
 private static CompanyProposal approvedProposal(String key,CompanyProposalType type,UUID companyId){if(key==null||!key.startsWith("proposal-"))return null;try{CompanyProposal p=CompanyProposalManager.getProposal(UUID.fromString(key.substring("proposal-".length())));return p!=null&&p.isExecutableAuthorization(type,companyId)?p:null;}catch(IllegalArgumentException ignored){return null;}}
 private static boolean ensureCapacity(Map<UUID,?> actions){if(actions.size()<MAX_ACTIONS)return true;Iterator<? extends Map.Entry<UUID,?>>it=actions.entrySet().iterator();while(actions.size()>=MAX_ACTIONS&&it.hasNext()){Object action=it.next().getValue();CapitalActionStatus status=action instanceof BuybackPlan p?p.status():action instanceof TenderOffer o?o.status():CapitalActionStatus.OPEN;if(status!=CapitalActionStatus.OPEN)it.remove();}return actions.size()<MAX_ACTIONS;}
 private static UUID escrow(UUID id){return UUID.nameUUIDFromBytes(("corporate-action-escrow:"+id).getBytes(StandardCharsets.UTF_8));}private static void ensureZeroEscrow(UUID id){if(!AccountManager.getAccounts().containsKey(id))AccountManager.getAccount(id).setBalance(0);}private static long multiply(long a,long b){try{return Math.multiplyExact(a,b);}catch(ArithmeticException e){return -1;}}private static long sum(Map<UUID,Long>m){BigInteger n=BigInteger.ZERO;for(long v:m.values())n=n.add(BigInteger.valueOf(v));return n.min(BigInteger.valueOf(Long.MAX_VALUE)).longValue();}private static long add(long a,long b){return a>Long.MAX_VALUE-b?Long.MAX_VALUE:a+b;}private static void announce(UUID c,CorporateAnnouncement.Type t,long d,UUID b,String key,String details){putAnnouncementDirect(new CorporateAnnouncement(UUID.randomUUID(),c,t,d,b,key,details));}private static void record(UUID from,UUID to,long amount,TransactionType type,UUID player,String object,long q){AccountManager.addTransactionRecord(new TransactionRecord(from,to,amount,type,player,object,q));}public record Result(boolean success,UUID id,String message){static Result ok(UUID id,String m){return new Result(true,id,m);}static Result fail(String m){return new Result(false,null,m);}}
}
